--限制拉取赛季
local _isCanGetTournament = true;

local InitiallyTimeOffset = 0;                  -- 本地时间与服务器时间偏移值
local Threshold = 1;                            -- offset阈值
--赛事条目倒计时函数
function IndiaCompetitionUI.CountDownTimerFunc()
    local currentTimeOffset = FuncUtil.GetServerTimeInSec() - os.time();
    if math.abs(currentTimeOffset - InitiallyTimeOffset) > Threshold then
        InitiallyTimeOffset = currentTimeOffset;    -- 时间差别过大刷新偏移值
    end
    BP_INDIA_SERVER_TIME = os.time() + InitiallyTimeOffset;

    for k,v in pairs(BP_ARRAY_IndiaCompetition_EntranceList) do
        if v.next_state_time and BP_INDIA_SERVER_TIME - v.next_state_time > 1 and _isCanGetTournament then
            IndiaChampionShipLogic.get_tournaments_req()
            _isCanGetTournament = false;
        end
    end
    LuaClassObj.HandleUIMessage(bp_india_championship, "RefreshTimer")
end

--新增需求 匹配失败 打开界面时候弹提示。并且只弹一次
local _show_match_fail_pop = false;
local _fail_pop_id = 0;
function IndiaCompetitionUI:Show()
    BP_INDIA_COMPETITION_MONEY_NUM = DataMgr.ticket;
    local itemData = DataMgr.GetHallDepotItemDataByResID(1702018);
    BP_INDIA_TICKET = itemData and itemData.count or 0;
    LuaClassObj.HandleDynamicCreation(bp_india_championship);
    LuaClassObj.HandleUIMessage(bp_india_championship, "UIShow")
    EventSystem:registEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, _UpdateUC);
    IndiaChampionShipLogic.get_tournaments_req()
    IndiaChampionShipLogic.get_tournament_score_req()
    if IndiaCompetitionUI.countDownTimer then
        Timer.RemoveTimer(IndiaCompetitionUI.countDownTimer);
    end
    InitiallyTimeOffset = FuncUtil.GetServerTimeInSec() - os.time();
    IndiaCompetitionUI.countDownTimer = Timer.InsertTimer(1,IndiaCompetitionUI.CountDownTimerFunc, true, true);    
    if _show_match_fail_pop then
        DataMgr.ShowNoticeByID(6651);
        _show_match_fail_pop = false;
    end
    
    local mall = DataMgr.GetNewbieGuideValue(DataMgr.NEWBIE_GUIDE_MODULE_ID_INDIA_CHAMPIONSHIP,Newbie_Guide_India_Championship_Mall);
    if nil == mall then
        LuaClassObj.HandleUIMessageNoFetch(bp_india_championship, "ShowMallEffect")
    end
    UIManager.Show(eUIType.eIndiaChampionShipMain);
    IndiaCompetitionIntroduceUI.CheckAndShow()
end

function IndiaCompetitionUI:Hide()
    EventSystem:unregistEvent(EVENTTYPE_DATA_MGR, EVENTID_DATAMGR_TICKET_CHANGE, _UpdateUC);
    if IndiaCompetitionUI.countDownTimer then
        Timer.RemoveTimer(IndiaCompetitionUI.countDownTimer);
    end
    UIManager.Hide(eUIType.eIndiaChampionShipMain)
    LuaClassObj.HandleUIMessageNoFetch(bp_india_championship, "UIHide")
end

