function EVENT_INDIA_ITEM_CLICK()
    log("item click index = "..tostring(BP_INDIA_ITEM_INDEX))
    local item_data = BP_ARRAY_IndiaCompetition_EntranceList[BP_INDIA_ITEM_INDEX+1]
    if item_data then
        if item_data.state == 2 and item_data.user_state == 0 then
            IndiaSignUpUI.Show(item_data)
            --IndiaChampionShipLogic.tournament_enroll_req(item_data.id, 1006)
        elseif item_data.state == 4 and item_data.user_state == 1 then
            IndiaChampionShipLogic.enter_tournament_room_req()
        end
    end
end

