function IndiaCompetitionUI:SetTournamentData(tournaments)
    BP_INDIA_SERVER_TIME = FuncUtil.GetServerTimeInSec();
    BP_INDIA_IS_MATCH_SUCESS = IndiaChampionShipLogic.matchState;
    BP_ARRAY_IndiaCompetition_EntranceList = {}
    BP_INDIA_HAS_ENROLL = false;
    for k,v in pairs(tournaments) do
        local item = {};
        item.id = k;
        --当前状态
        item.state = 0;
        --报名消耗
        item.cost_resid = v.type_data.cost[1702018] and v.type_data.cost[1702018] or -1;
        item.cost = v.type_data.cost[1006] and v.type_data.cost[1006] or -1;
        --比赛人数
        item.enroll_count = v.type_data.enroll_count and v.type_data.enroll_count or 0;
        item.enroll_limit = v.type_data.enroll_limit;
        --标题
        item.title = v.title and v.title or 0;
        --玩家状态
        item.user_state = v.user_data.enroll_state;
        if item.user_state == 1 then
            BP_INDIA_HAS_ENROLL = true;
        end
        --比赛开始时间
        item.start_time = v.type_data.start_time;
        --等级限制
        item.level_limit = v.type_data.level_limit;
        --赛段限制
        item.ratinglimit = v.type_data.ratinglimit;
        --模式组id
        item.mode_group = v.type_data.mode_group;
        --可获得积分
        item.earn_score = v.type_data.earn_score;
        --开始报名时间字符串
        item.start_enroll_time_str = os.date("%m.%d", v.type_data.enroll_begTime)
        --比赛额度（1 2 3）
        item.grade = v.type_data.grade

        --未开启
        if BP_INDIA_SERVER_TIME < v.type_data.enroll_begTime then
            item.next_state_time = v.type_data.enroll_begTime;
            item.state = 1;
        --报名阶段
        elseif BP_INDIA_SERVER_TIME > v.type_data.enroll_begTime and BP_INDIA_SERVER_TIME < v.type_data.enroll_endTime then
            item.next_state_time = v.type_data.enroll_endTime;
            item.state = 2;
        --匹配阶段（策划改需求要求隐藏此阶段。但逻辑上还有）
        elseif BP_INDIA_SERVER_TIME > v.type_data.enroll_endTime and BP_INDIA_SERVER_TIME < v.type_data.enter_time then
            item.next_state_time = v.type_data.enter_time;
            item.state = 3;
        --进房阶段
        elseif BP_INDIA_SERVER_TIME > v.type_data.enter_time and BP_INDIA_SERVER_TIME < v.type_data.start_time then
            item.next_state_time = v.type_data.start_time;
            item.state = 4;
        end

        --已报满
        if item.enroll_count == item.enroll_limit and item.user_state ~= 1 then
            item.user_state = 3;
        end

        --等级不足
        if item.level_limit > DataMgr.roleData.level and item.user_state ~= 1 then
            item.user_state = 4;
        end

        if item.state ~= 0 then
            log("IndiaCompetitionUI:SetTournamentData id = "..tostring(k))
            table.insert(BP_ARRAY_IndiaCompetition_EntranceList,item);
        end
    end
    log("IndiaCompetitionUI:SetTournamentData servertime = "..tostring(BP_INDIA_SERVER_TIME))
    table.sort(BP_ARRAY_IndiaCompetition_EntranceList,function(a,b) return a.cost < b.cost; end )
    _isCanGetTournament = true;
    LuaClassObj.HandleUIMessage(bp_india_championship, "RefreshEntranceItems")
end

--刷新参赛券与积分
function IndiaCompetitionUI:SetCreditAndTicket()
    local itemData = DataMgr.GetHallDepotItemDataByResID(1702018);
    BP_INDIA_TICKET = itemData and itemData.count or 0;
    BP_INDIA_CREDIT = IndiaChampionShipLogic.Score;
    LuaClassObj.HandleUIMessage(bp_india_championship, "RefreshPlayerUC")
end

function IndiaCompetitionUI:OnReceiveMatchFail(tournaments)
    for k,v in pairs(tournaments) do
        if v.user_data.enroll_state == 1 and k ~= _fail_pop_id then
            _fail_pop_id=k;
            _show_match_fail_pop = true;
            break;
        end
    end
end